package org.kanger;
import java.util.*;
import org.kanger.ContextProductionCapture.Source;
import org.kanger.ContextProductionCapture.Support;
import org.kanger.ContextSignedUnaryModel.Interpretation;
import org.kanger.ContextSignedUnaryBranchModel.*;
import org.kanger.ContextWitnessResultTransport.*;
import org.kanger.ContextUniversalInputResiduals.Residual;
import org.kanger.ContextUniversalInputResiduals.Literal;
import org.kanger.ContextUniversalInputResiduals.Term;

/** Direct exact final inventory/model audit; never invokes model/branch/stopping builders. */
final class ContextSignedUnaryBranchModelAudit {
 static final class Receipt {final Ledger ledger;private Receipt(Ledger ledger){this.ledger=ledger;}}
 private static void require(boolean b,String why){if(!b)throw new IllegalStateException(why);}
 private static void take(Ledger l,int[] index,Kind kind,Cut cut,Object carrier,Support support,Runnable work){work.run();require(index[0]<l.policy.obligations&&index[0]<l.obligations.size(),"Complete final obligation inventory required");Obligation o=l.obligations.get(index[0]++);require(o!=null&&o.kind==kind&&o.cut.equals(cut)&&o.carrier==carrier&&o.support==support,"Different actual final carrier/Source alternative/grade");}
 private static int fixed(Interpretation m,SemanticTermSnapshot v,Runnable work){require(v!=null,"Actual final ordinary value required");for(int n=0;n<m.points.size();n++){work.run();if(m.points.get(n).semanticallyEquals(v))return n;}throw new IllegalStateException("Final constant absent from unchanged original named basis");}
 private static void predicate(String name,int arity,Set<String> names,Runnable work){work.run();require(name!=null&&!name.isEmpty()&&name.length()<=256&&arity==1,"Final uninterpreted unary atom required");names.add(name);}
 private static void origin(Origin o,Set<Origin> origins,Set<Source> bundles,Runnable work){work.run();require(o!=null&&o.binder==0&&bundles.contains(o.source),"Final Origin must belong to actual original one-binder bundle Source");origins.add(o);}
 private static void atom(Item i,Interpretation m,Set<String> names,Set<Origin> origins,Set<Source> bundles,Runnable work){predicate(i.atom.predicate,i.atom.arguments.size(),names,work);Slot s=i.atom.arguments.get(0);if(s.origin!=null){require(s.value==null,"Origin cannot be an ordinary final constant");origin(s.origin,origins,bundles,work);}else fixed(m,s.value,work);}
 private static void clause(Residual c,Interpretation m,Set<String> names,Set<Origin> origins,Set<Source> bundles,Runnable work){require(c!=null&&!c.literals.isEmpty()&&c.literals.size()<=8&&c.variables.size()<=1,"Actual nonempty single-variable final unary clause required");Set<Integer> variables=new HashSet<>();Set<Origin> actual=new HashSet<>();for(Literal a:c.literals){predicate(a.predicate,a.arguments.size(),names,work);Term t=a.arguments.get(0);require(t.variable>=-1,"Invalid final universal slot");if(t.variable>=0){require(t.origin==null&&t.value==null,"Final universal variable cannot alias Origin/value");variables.add(t.variable);}else if(t.origin!=null){require(t.value==null,"Final Origin cannot alias value");origin(t.origin,origins,bundles,work);actual.add(t.origin);}else fixed(m,t.value,work);}require(variables.equals(c.variables)&&actual.equals(c.origins),"Different exact final variable/Origin coverage");}
 private static Residual residual(Obligation o){switch(o.kind){case UNIT:return ((ContextUniversalSignedUnitExchange.Unit)o.carrier).clause;case COMPOUND:return ((ContextUniversalCompoundExchange.ResidualProof)o.carrier).clause;case TERMINAL:return ((ContextUniversalFrozenConstraints.Proof)o.carrier).clause;default:throw new IllegalStateException("Fixed atom is not a residual");}}
 private static boolean value(Interpretation m,Extension e,String predicate,boolean positive,int point,Runnable work){work.run();List<Boolean> row=m.truth.get(predicate);if(row==null)row=e.truth.get(predicate);return row.get(point)==positive;}
 private static void evaluate(Obligation o,Interpretation m,Extension e,Runnable work){work.run();if(o.kind==Kind.COMMON||o.kind==Kind.PRIVATE){Item i=(Item)o.carrier;Slot s=i.atom.arguments.get(0);int point=s.origin==null?fixed(m,s.value,work):e.denotations.get(s.origin);require(value(m,e,i.atom.predicate,i.atom.positive,point,work),"Actual final common/private atom false in proposed extension; not a refutation");return;}Residual c=residual(o);int count=c.variables.isEmpty()?1:m.points.size()+1;for(int variable=0;variable<count;variable++){work.run();boolean yes=false;for(Literal a:c.literals){Term t=a.arguments.get(0);int point=t.variable>=0?variable:t.origin!=null?e.denotations.get(t.origin):fixed(m,t.value,work);yes|=value(m,e,a.predicate,a.positive,point,work);}require(yes,"Actual final unit/compound/terminal clause false in proposed extension; not a no-model proof");}}
 static Receipt inspect(Ledger l,ContextSignedUnaryModelAudit.Receipt original,ContextSignedWitnessNativeBranch.Receipt branch,Map<Cut,Extension> extensions,Policy p,int maximumWork){
  require(l!=null&&original!=null&&branch!=null&&extensions!=null&&extensions.size()<=16&&p!=null&&maximumWork>0&&l.original==original&&l.branch==branch&&l.extensions.equals(extensions)&&l.policy==p,"Exact original/final model request ledger required");new Policy(p.obligations,p.work,p.capacity);ContextSignedUnaryModel.Ledger base=original.ledger;require(branch.x==base.x&&branch.foreign.equals(base.foreign)&&branch.status==ContextSignedWitnessNativeBranch.Status.QUIESCENT_SUPPLIED,"Same actual original snapshot family and qualified final stop required");
  ContextSignedUnaryModelAudit.check(original,base.x,base.foreign,base.models,base.policy,maximumWork);ContextSignedWitnessNativeBranchAudit.check(branch,base.x,base.foreign,branch.policy,maximumWork,p.capacity);ContextSignedWitnessContinuationScope.Receipt scope=branch.termination.result.output;ContextSignedWitnessStop.Receipt stop=branch.termination.result.stopping;require(stop!=null&&stop.terminal.scope==scope&&base.models.keySet().equals(stop.terminal.checks.keySet())&&l.extensions.keySet().equals(base.models.keySet()),"Actual final scope and ALL logical model cuts required");Runnable work=ContextGroundProductionRounds.budget(maximumWork);int[] index={0};Set<Source> bundles=new HashSet<>();for(ContextSignedUnaryModel.Row row:base.rows){work.run();if(row.entry.bundle!=null)bundles.add(row.entry.source);}
  // Independently walk ACTUAL final carriers/proofs, retaining EVERY Source alternative and owner.
  for(Cut cut:stop.terminal.checks.keySet()){for(Item i:scope.current().packet.items)for(Support s:i.proofs)take(l,index,Kind.COMMON,cut,i,s,work);PrivatePool pool=scope.current().privatePools.get(cut);if(pool!=null)for(Item i:pool.local.items)for(Support s:i.proofs)take(l,index,Kind.PRIVATE,cut,i,s,work);for(ContextUniversalSignedUnitExchange.Unit u:stop.units.units)take(l,index,Kind.UNIT,cut,u,u.support,work);for(ContextUniversalCompoundExchange.ResidualProof c:stop.compounds.clauses)take(l,index,Kind.COMPOUND,cut,c,c.support,work);for(ContextUniversalFrozenConstraints.Proof proof:stop.terminal.checks.get(cut).proofs)take(l,index,Kind.TERMINAL,cut,proof,proof.support,work);}require(index[0]==l.obligations.size(),"Extra/lost actual final obligation or Source alternative");
  Map<Cut,Set<String>> names=new LinkedHashMap<>();Map<Cut,Set<Origin>> origins=new LinkedHashMap<>();for(Cut cut:base.models.keySet()){names.put(cut,new HashSet<>());origins.put(cut,new HashSet<>());}for(Obligation o:l.obligations){Interpretation m=base.models.get(o.cut);if(o.kind==Kind.COMMON||o.kind==Kind.PRIVATE)atom((Item)o.carrier,m,names.get(o.cut),origins.get(o.cut),bundles,work);else clause(residual(o),m,names.get(o.cut),origins.get(o.cut),bundles,work);}
  // WHOLE final shape/extension preflight before truth. Original cells/basis cannot be replaced.
  for(Cut cut:base.models.keySet()){work.run();Interpretation m=base.models.get(cut);Extension e=l.extensions.get(cut);require(e!=null&&names.get(cut).containsAll(m.truth.keySet())&&names.get(cut).size()<=base.policy.predicates,"Actual bounded final extension required");Set<String> additional=new HashSet<>(names.get(cut));additional.removeAll(m.truth.keySet());require(e.truth.keySet().equals(additional)&&e.denotations.keySet().equals(origins.get(cut)),"Exact additional predicates/ALL final Origin denotations required, no original truth override");for(List<Boolean> row:e.truth.values()){work.run();require(row!=null&&row.size()==m.points.size()+1,"Additional truth needs unchanged named basis plus ALL-other default");for(Boolean b:row){work.run();require(b!=null,"Every additional truth cell required");}}Set<Source> retained=new HashSet<>();for(Map.Entry<Origin,Integer> denotation:e.denotations.entrySet()){work.run();Origin o=denotation.getKey();origin(o,new HashSet<>(),bundles,work);Integer point=denotation.getValue();require(point!=null&&point>=0&&point<m.points.size(),"Concrete named value for every final Origin required");if(m.witnesses.containsKey(o.source)){require(point.equals(m.witnesses.get(o.source)),"Original whole-bundle assignment cannot change at final barrier");retained.add(o.source);}}require(retained.equals(m.witnesses.keySet()),"Every original local/common binder must retain actual final Origin");}
  for(Obligation o:l.obligations)evaluate(o,base.models.get(o.cut),l.extensions.get(o.cut),work);return new Receipt(l);
 }
 static void check(Receipt r,ContextSignedUnaryModelAudit.Receipt original,ContextSignedWitnessNativeBranch.Receipt branch,Map<Cut,Extension> extensions,Policy p,int work){require(r!=null,"Actual final unary model receipt required");inspect(r.ledger,original,branch,extensions,p,work);}
}
